/**
 * Generates AI-facing documentation from source of truth (never hand-edit outputs):
 *
 *   - `docs/errors.md`  ← `BUNEST_ERROR_CATALOG` (packages/core/src/errors/error-catalog.ts)
 *   - `llms.txt`        ← package.json metadata + docs index (https://llmstxt.org)
 *   - `llms-full.txt`   ← llms.txt + runtime public value exports + AGENTS.md + quickstart + errors
 *
 * Usage:
 *   bun run ai:docs          # write files
 *   bun run ai:docs --check  # exit 1 if any generated file is stale (CI / tests)
 */
import {
  BUNEST_ERROR_CATALOG,
  getErrorDocsUrl,
  type BunestErrorCatalogEntry,
} from "../packages/core/src/errors/error-catalog";

export const REPO_ROOT = `${import.meta.dir}/..`;

interface PackageExportEntry {
  readonly bun?: string;
  readonly types?: string;
}

interface PackageMeta {
  readonly dir: string;
  readonly name: string;
  readonly description: string;
  readonly subpaths: readonly { subpath: string; file: string }[];
}

const GENERATED_BANNER =
  "<!-- AUTO-GENERATED by scripts/ai-docs.ts — do not edit by hand. Run `bun run ai:docs`. -->";

const DOCS_INDEX: readonly { title: string; path: string; summary: string }[] = [
  { title: "AGENTS.md", path: "AGENTS.md", summary: "Rules and verification loop for AI coding agents working in this repo" },
  { title: "Quickstart", path: "docs/quickstart.md", summary: "Build, document, and test a validated REST CRUD API" },
  { title: "Error catalog", path: "docs/errors.md", summary: "Every BUNEST_E* error code with ordered fixes" },
  { title: "Architecture", path: "docs/architecture.md", summary: "Package DAG, bootstrap compiler, HTTP pipeline, DI scopes" },
  { title: "Security", path: "docs/security.md", summary: "Validation defaults, headers, CORS, JWT, rate limiting" },
  { title: "Testing", path: "docs/testing.md", summary: "TestingModule, overrides, TestClient, request(app)" },
  { title: "NestJS migration", path: "docs/nestjs-migration.md", summary: "Import map and differences vs NestJS" },
  { title: "ADRs", path: "docs/adr/README.md", summary: "Authoritative architectural decisions" },
];

async function readPackages(): Promise<PackageMeta[]> {
  const files = await Array.fromAsync(
    new Bun.Glob("packages/*/package.json").scan({ cwd: REPO_ROOT }),
  );
  const metas: PackageMeta[] = [];
  for (const rel of files.map((f) => f.replace(/\\/g, "/")).sort()) {
    const pkg = (await Bun.file(`${REPO_ROOT}/${rel}`).json()) as {
      name: string;
      description?: string;
      exports?: Record<string, string | PackageExportEntry>;
    };
    const dir = rel.slice(0, -"/package.json".length);
    const subpaths: { subpath: string; file: string }[] = [];
    for (const [subpath, entry] of Object.entries(pkg.exports ?? {})) {
      if (typeof entry !== "object" || !entry.bun) continue;
      subpaths.push({ subpath, file: `${dir}/${entry.bun.replace(/^\.\//, "")}` });
    }
    metas.push({ dir, name: pkg.name, description: pkg.description ?? "", subpaths });
  }
  return metas;
}

function importPath(subpath: string, name: string): string {
  return subpath === "." ? name : `${name}/${subpath.replace(/^\.\//, "")}`;
}

// ---------------------------------------------------------------------------
// docs/errors.md
// ---------------------------------------------------------------------------

export function buildErrorsMarkdown(): string {
  const entries = Object.values(BUNEST_ERROR_CATALOG) as BunestErrorCatalogEntry[];
  const out: string[] = [
    GENERATED_BANNER,
    "",
    "# Bunest Error Catalog",
    "",
    "Every bootstrap and routing error thrown by `@bunest/core` carries a stable `code` (`err.code`).",
    "Use `toBunestErrorReport(err)` for a JSON report or `formatBunestErrorForAgent(err)` for a compact",
    "text rendering. Fixes are ordered: try the first one first.",
    "",
    "| Code | Exception | Title |",
    "| --- | --- | --- |",
    ...entries.map(
      (e) => `| [\`${e.code}\`](#${e.code.toLowerCase()}) | \`${e.name}\` | ${e.title} |`,
    ),
    "",
  ];
  for (const e of entries) {
    out.push(`## ${e.code}`, "", `**\`${e.name}\` — ${e.title}**`, "", e.summary, "", "Fixes (in order):", "");
    e.fixes.forEach((fix, i) => out.push(`${i + 1}. ${fix}`));
    out.push("");
    if (e.example) out.push("```ts", e.example, "```", "");
  }
  return `${out.join("\n").trimEnd()}\n`;
}

// ---------------------------------------------------------------------------
// llms.txt / llms-full.txt
// ---------------------------------------------------------------------------

const AGENT_ESSENTIALS = [
  "Runtime is Bun >= 1.4.5 only; never import `node:*`, Express, Fastify, RxJS or `reflect-metadata` (a Reflect metadata shim is built in).",
  "Legacy decorators: tsconfig needs `experimentalDecorators` + `emitDecoratorMetadata`; `verbatimModuleSyntax` is on.",
  "Value-import every DI class, DTO and entity (never `import type`), otherwise constructor injection breaks at runtime.",
  "Canonical names: `BunestFactory` (not `NestFactory`), `@OrmRepository` + `CrudRepository`, validators from `@bunest/validation/validator` (not `class-validator`).",
  "Interceptors return Promises (`CallHandler.handle(): Promise<T>`), not Observables.",
  "After every change run `bunest verify --reporter=agent` and fix the first failing step.",
  "Bootstrap errors have stable codes (`err.code`, e.g. `BUNEST_E001`); see docs/errors.md for ordered fixes.",
];

export async function buildLlmsTxt(packages?: PackageMeta[]): Promise<string> {
  const pkgs = packages ?? (await readPackages());
  const out: string[] = [
    "# Bunest",
    "",
    "> NestJS-style backend framework built natively on Bun: modules, constructor DI, decorators, guards, pipes, interceptors, validation, OpenAPI, ORM and testing — compiled to native `Bun.serve({ routes })` at bootstrap with zero external runtime dependencies.",
    "",
    "Essentials for AI agents:",
    "",
    ...AGENT_ESSENTIALS.map((r) => `- ${r}`),
    "",
    "## Docs",
    "",
    ...DOCS_INDEX.map((d) => `- [${d.title}](${d.path}): ${d.summary}`),
    "",
    "## Packages",
    "",
    ...pkgs.map((p) => {
      const subs = p.subpaths.map((s) => `\`${importPath(s.subpath, p.name)}\``).join(", ");
      return `- [${p.name}](${p.dir}): ${p.description.replace(/\.?\s*$/, ".")} Imports: ${subs}`;
    }),
    "",
    "## Optional",
    "",
    "- [llms-full.txt](llms-full.txt): Full public value-export index per import path, AGENTS.md, quickstart and error catalog in one file",
    "- [Examples](examples): Runnable reference apps (hello-world, rest-crud, starter, auth-jwt-sqlite, websocket-chat, distributed-worker, production-rest-postgres, vscode-extension-showcase)",
    "",
  ];
  return out.join("\n");
}

async function listValueExports(file: string): Promise<string[]> {
  const mod = (await import(`${REPO_ROOT}/${file}`)) as Record<string, unknown>;
  return Object.keys(mod)
    .filter((k) => k !== "default")
    .sort((a, b) => a.localeCompare(b));
}

async function readOptional(relPath: string): Promise<string | undefined> {
  const file = Bun.file(`${REPO_ROOT}/${relPath}`);
  return (await file.exists())
    ? (await file.text()).replace(/\r\n/g, "\n")
    : undefined;
}

export async function buildLlmsFullTxt(packages?: PackageMeta[]): Promise<string> {
  const pkgs = packages ?? (await readPackages());
  const out: string[] = [await buildLlmsTxt(pkgs), "---", "", "# Public API index", ""];
  out.push(
    "Runtime value exports per import path (types/interfaces omitted). Import exactly from the listed path.",
    "",
  );
  for (const p of pkgs) {
    out.push(`## ${p.name}`, "", p.description, "");
    for (const s of p.subpaths) {
      const names = await listValueExports(s.file);
      out.push(`### \`${importPath(s.subpath, p.name)}\` (${names.length})`, "", names.join(", "), "");
    }
  }
  for (const rel of ["AGENTS.md", "docs/quickstart.md"]) {
    const text = await readOptional(rel);
    if (text) out.push("---", "", `<!-- source: ${rel} -->`, "", text.trim(), "");
  }
  out.push("---", "", "<!-- source: docs/errors.md -->", "", buildErrorsMarkdown().replace(`${GENERATED_BANNER}\n\n`, "").trim(), "");
  return `${out.join("\n").trimEnd()}\n`;
}

export async function buildAllAiDocs(): Promise<Record<string, string>> {
  const pkgs = await readPackages();
  return {
    "docs/errors.md": buildErrorsMarkdown(),
    "llms.txt": await buildLlmsTxt(pkgs),
    "llms-full.txt": await buildLlmsFullTxt(pkgs),
  };
}

/** Sanity: every catalog entry must have a resolvable docs anchor. */
export function catalogDocsUrls(): string[] {
  return Object.keys(BUNEST_ERROR_CATALOG).map(getErrorDocsUrl);
}

if (import.meta.main) {
  const check = Bun.argv.includes("--check");
  const outputs = await buildAllAiDocs();
  const stale: string[] = [];
  for (const [rel, content] of Object.entries(outputs)) {
    const path = `${REPO_ROOT}/${rel}`;
    const current = (await Bun.file(path).exists())
      ? (await Bun.file(path).text()).replace(/\r\n/g, "\n")
      : undefined;
    if (current === content) continue;
    if (check) {
      stale.push(rel);
    } else {
      await Bun.write(path, content);
      console.log(`[ai-docs] wrote ${rel} (${(content.length / 1024).toFixed(1)} KB)`);
    }
  }
  if (check && stale.length > 0) {
    console.error(`[ai-docs] stale generated files: ${stale.join(", ")}. Run \`bun run ai:docs\`.`);
    process.exit(1);
  }
  if (check) console.log("[ai-docs] all generated AI docs are up to date.");
  process.exit(0);
}
